def flatten_list(nested_list):
    result = []
    for item in nested_list:
        if isinstance(item, list):
            result.extend(item)
        else:
            result.append(item)
    return result

def remove_odd(numbers):
    """Remove odd numbers from a given list."""
    return [num for num in numbers if num % 2 == 0]

def multiple_to_single(numbers):
    """
    Join a list of multiple integers into a single integer.

    Args:
        numbers: A list of integers

    Returns:
        A single integer formed by concatenating all numbers
    """
    if not numbers:
        return 0

    # Handle the case where the first number is negative
    if numbers[0] < 0:
        # Start with the negative sign and the absolute value of the first number
        result = str(numbers[0])
        # Append the rest of the numbers as strings
        for num in numbers[1:]:
            result += str(abs(num))
        return int(result)
    else:
        # All numbers are non-negative, just concatenate them
        result = ''.join(str(num) for num in numbers)
        return int(result)

def find_Odd_Pair(arr, n):
    """
    Count the number of pairs whose XOR value is odd.
    XOR is odd when one number is even and the other is odd.
    """
    odd_count = 0
    even_count = 0

    for num in arr:
        if num % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    return odd_count * even_count

