def largest_subset(numbers):
    if not numbers:
        return 0

    # Sort the numbers
    sorted_nums = sorted(numbers)
    n = len(sorted_nums)

    # dp[i] = length of longest divisibility chain ending at sorted_nums[i]
    dp = [1] * n

    for i in range(n):
        for j in range(i):
            # If sorted_nums[j] divides sorted_nums[i], we can extend the chain
            if sorted_nums[i] % sorted_nums[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def skjkasdkd(lst):
    """You are given a list of integers.
    You need to find the largest prime value and return the sum of its digits.

    Examples:
    For lst = [0,3,2,1,3,5,7,4,5,5,5,2,181,32,4,32,3,2,32,324,4,3] the output should be 10
    For lst = [1,0,1,8,2,4597,2,1,3,40,1,2,1,2,4,2,5,1] the output should be 25
    For lst = [1,3,1,32,5107,34,83278,109,163,23,2323,32,30,1,9,3] the output should be 13
    For lst = [0,724,32,71,99,32,6,0,5,91,83,0,5,6] the output should be 11
    For lst = [0,81,12,3,1,21] the output should be 3
    For lst = [0,8,1,2,1,7] the output should be 7
    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    # Find the largest prime in the list
    largest_prime = None
    for num in lst:
        if is_prime(num):
            if largest_prime is None or num > largest_prime:
                largest_prime = num

    # Sum the digits of the largest prime
    digit_sum = sum(int(digit) for digit in str(largest_prime))
    return digit_sum

def snake_to_camel(snake_str):
    """Convert a snake case string to camel case string."""
    words = snake_str.split('_')
    return ''.join(word.capitalize() for word in words)

def odd_Equivalent(binary_string, n):
    count = 0
    for i in range(n):
        # Rotate the string left by i positions
        rotated = binary_string[i:] + binary_string[:i]
        # Check if the last bit is 1 (odd number)
        if rotated[-1] == '1':
            count += 1
    return count

def tuple_intersection(list1, list2):
    # Normalize tuples by sorting them (order-independent comparison)
    # Create sets of normalized tuples
    set1 = {tuple(sorted(t)) for t in list1}
    set2 = {tuple(sorted(t)) for t in list2}

    # Find intersection
    intersection = set1 & set2

    return intersection

